INSERT INTO `factions` (`id`, `name`, `slug`, `short_description`, `flag_image`, `color`, `nation_bank_credits`, `lore`, `created_at`, `updated_at`) VALUES
(1, 'Red Empire', 'red-empire', 'Industrial firepower and rigid command discipline.', NULL, '#ff0000', 138382, 'The Red Empire believes Plastica belongs to whoever can hold the line the longest.', '2026-03-12 19:18:23', '2026-08-07 19:43:19'),
(2, 'Kingdom of Greenland', 'kingdom-of-greenland', 'Royal bureaucracy with disciplined civic order.', NULL, '#4db300', 1526584, 'Greenland blends court politics with stubborn territorial defense.', '2026-03-12 19:18:23', '2026-08-04 20:40:04'),
(3, 'Tan Empire', 'tan-empire', 'Expansionist machine built on logistics and rank.', NULL, '#ffe07a', 1168, 'The Tan Empire moves methodically, turning roads and depots into leverage.', '2026-03-12 19:18:23', '2026-08-06 22:30:24'),
(4, 'Tangerian Republic', 'tangerian-republic', 'Republican traders backed by citizen militias.', NULL, '#ff8800', 13896, 'Tangeria thrives where commerce and local government overlap.', '2026-03-12 19:18:23', '2026-08-08 02:52:03'),
(5, 'Imperial Graul', 'imperial-graul', 'Hard-edged martial society with elite officer culture.', NULL, '#858585', 50000, 'Graul rewards battlefield dominance and political loyalty.', '2026-03-12 19:18:23', '2026-08-08 00:17:11'),
(6, 'Kingdom of Blutannia', 'kingdom-of-blutannia', 'Naval aristocracy with old-money influence.', NULL, '#0400ff', 11000, 'Blutannia projects power through prestige, finance, and ceremony.', '2026-03-12 19:18:23', '2026-08-08 02:34:24'),
(7, 'Obsidian Purl', 'obsidian-purl', 'Secretive technocrats with a fortified economy.', NULL, '#8300b3', 0, 'Obsidian Purl turns scarcity into leverage and information into power.', '2026-03-12 19:18:23', '2026-03-17 01:56:11'),
(8, 'New Purlanese Republic', 'new-purlanese-republic', 'Young republic where reformers and merchants collide.', NULL, '#ef0fff', 0, 'The republic promises mobility, but every office is contested.', '2026-03-12 19:18:23', '2026-03-17 01:56:01');
INSERT INTO `game_events` (`id`, `faction_id`, `created_by_user_id`, `title`, `body`, `is_enabled`, `ends_at`, `xp_multiplier_enabled`, `xp_multiplier`, `credit_multiplier_enabled`, `credit_multiplier`, `created_at`, `updated_at`) VALUES
(1, NULL, 2, 'Community Week', 'As a thankyou to those who have been actively engaging and playing, there is now a 1.5x multiplier for both credits and XP. Enjoy! (Ends 09/AUG/2026.)', 1, '2026-08-09 18:00:00', 1, 1.50, 1, 1.50, '2026-08-03 23:53:52', '2026-08-04 00:03:12');
INSERT INTO `game_jobs` (`id`, `name`, `slug`, `description`, `min_pay`, `max_pay`, `required_level`, `work_cooldown_minutes`, `stamina_decrease`, `experience_reward`, `working_display_message`, `is_starter`, `is_active`, `created_at`, `updated_at`) VALUES
(1, 'Begger', 'begger', 'The most simple job in Plastica. Beg for money.', 5, 30, 0, 2, 15, 5, 'Begging in the city.', 1, 1, '2026-03-16 23:06:48', '2026-08-03 22:49:20'),
(3, 'Street Food Vendor', 'street-food-vendor', 'It\'s time to cook.', 50, 60, 1, 2, 15, 5, 'creating and handing out plastic snacks.', 0, 1, '2026-07-06 01:57:57', '2026-08-04 00:14:03'),
(4, 'Private', 'private', 'You passed boot-camp... You can now officially serve in your nations army..', 65, 115, 5, 2, 15, 5, 'Cleaning their rifle.', 0, 1, '2026-07-06 02:03:09', '2026-08-03 22:49:20'),
(13, 'Citizen', 'citizen', 'Standard civilian, not working yet. Just living off a government granted salary, low but simple.', 30, 50, 1, 2, 10, 5, 'obtaining their welfare check from the government.', 0, 1, '2026-07-30 21:02:42', '2026-08-03 22:55:18'),
(14, 'Farmer', 'farmer', 'A standard civilian working on the farmland of their nation to provide food and supplies. This is a standard civil job.', 60, 65, 3, 2, 10, 13, 'Plowing the fields for food.', 0, 1, '2026-07-30 21:13:15', '2026-08-04 00:16:01'),
(15, 'Miner', 'miner', 'A miner\'s only purpose is to dig the rich materials from the earth and bring them up to the surface. A civil job.', 50, 100, 3, 2, 10, 10, 'Mining at the nations mining facilities.', 0, 1, '2026-07-30 21:18:19', '2026-08-03 22:49:20'),
(16, 'Mechanic', 'mechanic', 'A mechanic is tasked with vehicular repairs, including military vehicles and civil vehicles. A civil job.', 50, 115, 3, 2, 10, 10, 'Fixing tanks and cars.', 0, 1, '2026-07-30 21:28:06', '2026-08-03 22:49:20'),
(17, 'Bank Teller', 'bank teller', 'This job is a low tier bank job that falls in the civil sector. Station the bank front desk and help citizens manage their finances.', 60, 70, 3, 2, 10, 10, 'Managing the national banks', 0, 1, '2026-07-30 21:34:05', '2026-08-04 00:14:56'),
(18, 'Government Employee', 'government employee', 'Keeping the government archives organized is important... But cheap work. A civil job.', 45, 100, 3, 2, 10, 10, 'Filing away government paperwork', 0, 1, '2026-07-30 21:38:41', '2026-08-03 22:49:20'),
(19, 'Restaurant Waiter', 'restaurant waiter', 'A restaurant waiter is your basic level job where you tend tables and serve food. A civil job that most people obtain.', 50, 100, 3, 2, 10, 10, 'Tending tables/Serving food', 0, 1, '2026-07-30 21:44:31', '2026-08-03 22:49:20'),
(20, 'Lumberjack', 'lumberjack', 'Chopping trees in the forest and hauling it back to town... what a job.', 70, 120, 5, 2, 20, 15, 'chopping trees down and taking them downtown.', 0, 1, '2026-08-04 00:18:51', '2026-08-04 00:18:51');
